<?php
/** Admin view of unresolved dependencies for one game. */
declare(strict_types=1);
require_once __DIR__.'/lib/CatalogSupport.php';require_once __DIR__.'/lib/BaseGameProtection.php';require_once __DIR__.'/lib/CatalogDependencyDiagnostics.php';use UnrealDb\Catalog\Infrastructure\Persistence\PdoGameMissingDependencyQuery;catalog_start_session();
function game_missing_int(string $key,int $default=0):int{$v=filter_input(INPUT_GET,$key,FILTER_VALIDATE_INT);return$v===false||$v===null?$default:max(0,(int)$v);}function game_missing_type():string{$v=strtolower(trim((string)($_GET['dependency_type']??'all')));return$v==='base_game'?'base_game':'all';}function game_missing_url(int $gameId,string $type,array $params=[]):string{$q=array_merge(['game_id'=>$gameId,'dependency_type'=>$type],$params);$q=array_filter($q,static fn(mixed $v):bool=>$v!==null&&$v!==''&&$v!==0);return'game-missing.php?'.http_build_query($q);}function game_missing_import_class(string $p,string $n):string{return implode('.',array_values(array_filter([$p,$n],static fn(string $v):bool=>trim($v)!=='')));}function gm_match(bool $v):string{return$v?'<strong>✓ MATCH</strong>':'<strong class="gm-bad">✗ DIFFERENT</strong>';}
function gm_compare_row(string $label,string $expected,string $got,bool $match):string{$expected=$expected!==''?$expected:'(empty)';$got=$got!==''?$got:'(empty)';return'<tr class="'.($match?'gm-match-row':'gm-diff-row').'"><td>'.catalog_h($label).'</td><td class="mono">'.catalog_h($expected).'</td><td class="mono">'.catalog_h($got).'</td><td class="result">'.gm_match($match).'</td></tr>';}
try{$config=catalog_config();$db=catalog_db($config);if(!catalog_require_admin_page('Game Missing Dependencies'))exit;base_game_ensure($db);$games=catalog_all($db,'SELECT id,name,slug FROM ue_games ORDER BY name');$gameId=game_missing_int('game_id');$game=$gameId>0?catalog_one($db,'SELECT id,name,slug FROM ue_games WHERE id=?',[$gameId]):null;if(!$game)throw new RuntimeException('Choose a valid game from the Games page.');$type=game_missing_type();$baseGameOnly=$type==='base_game';$selectedPackage=substr(trim((string)($_GET['package']??'')),0,255);if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$q=new PdoGameMissingDependencyQuery($db);$scope=$baseGameOnly?$q->officialBaseGamePackageNames($gameId):null;$totals=$q->totals($gameId,$scope);$missingObjects=(int)$totals['missing_objects'];$missingPackages=(int)$totals['missing_packages'];$filesWithMissing=(int)$totals['files_with_missing'];$rows=$selectedPackage!==''?$q->detailRows($gameId,$selectedPackage,$scope,500,0):$q->missingRows($gameId,$scope,500,0);$packageRows=$q->packageRows($gameId,$scope,500,0);
foreach($rows as &$row){$path=(string)($row['required_object_path']??'');$parts=explode('.',$path);$row['import_object_name']=(string)(end($parts)?:'');$row['import_class_package']=(string)($row['class_package']??'');$row['import_class_name']=(string)($row['class_name']??'');$row['provider_candidates']=catalog_dependency_provider_candidates($db,$gameId,(int)$row['file_id'],(string)$row['required_package']);foreach($row['provider_candidates'] as &$provider){$provider['candidate_rows']=catalog_dependency_export_candidates($db,$row,(int)$provider['file_id']);foreach($provider['candidate_rows'] as &$candidate)$candidate['outer_path']=catalog_dependency_export_outer_path($db,(int)$provider['file_id'],(int)$candidate['outer_index'],(string)$row['required_package']);unset($candidate);}unset($provider);}unset($row);
$typeLabel=$baseGameOnly?'Official base-game dependencies only':'All missing dependencies';catalog_head('Missing Dependencies — '.(string)$game['name']);echo <<<'CSS'
<style>.game-missing-filter{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.game-missing-filter label{display:grid;gap:5px}.missing-summary{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin:16px 0}.missing-package-summary{display:flex;gap:8px;flex-wrap:wrap}.missing-package-pill{display:inline-flex;gap:7px;align-items:center;padding:7px 10px;border:1px solid var(--border,#2b3950);border-radius:8px}.missing-detail{border:1px solid var(--border,#2b3950);border-radius:10px;margin:0 0 12px;overflow:hidden}.missing-detail__title{padding:10px 14px;background:rgba(255,255,255,.035);display:flex;gap:12px}.missing-detail__grid{display:grid;grid-template-columns:minmax(250px,.8fr) minmax(300px,1fr) minmax(500px,2fr)}.missing-detail__cell{padding:12px 14px;min-width:0;overflow-wrap:anywhere}.missing-detail__cell+.missing-detail__cell{border-left:1px solid var(--border,#2b3950)}.missing-label{display:block;font-size:.82em;font-weight:700;margin-bottom:6px}.provider-block+.provider-block{margin-top:12px;padding-top:12px;border-top:1px solid var(--border,#2b3950)}.candidate{margin-top:8px;padding:10px;border:1px solid var(--border,#2b3950);border-radius:7px}.compare{width:100%;border-collapse:collapse;margin-top:8px}.compare th,.compare td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--border,#2b3950);vertical-align:top}.compare th{font-size:.82em}.compare td:first-child{font-weight:700;white-space:nowrap}.compare .result{white-space:normal}.gm-diff-row{background:rgba(220,60,60,.08)}.gm-bad{color:#ff7777}.gm-diff{display:grid;gap:2px;margin-top:5px;padding:6px 8px;border-left:3px solid #d9534f;background:rgba(220,60,60,.08);white-space:normal}.gm-result{margin-top:8px;padding:8px 10px;border-radius:6px;font-weight:700}.gm-result--bad{border:1px solid rgba(220,60,60,.45);background:rgba(220,60,60,.08)}.gm-result--good{border:1px solid rgba(60,180,100,.45);background:rgba(60,180,100,.08)}.gm-wanted{display:grid;gap:4px}.gm-wanted strong{font-size:1.05em}.mismatch-reason{margin-top:8px;font-weight:700}@media(max-width:900px){.missing-summary,.missing-detail__grid{grid-template-columns:1fr}.missing-detail__cell+.missing-detail__cell{border-left:0;border-top:1px solid var(--border,#2b3950)}.compare{font-size:.9em}}</style>
CSS;
echo CatalogUi::pageHeader('Missing Dependencies — '.(string)$game['name'],$typeLabel.'. Package availability and object resolution are separate checks.',['Games'=>'games.php','Global Missing Files'=>'missing.php','Game Files'=>'game-files.php?id='.$gameId]);echo '<section class="ui-section"><div class="ui-section__body"><form class="game-missing-filter" method="get"><label>Game<select name="game_id">';foreach($games as $g)echo'<option value="'.(int)$g['id'].'"'.((int)$g['id']===$gameId?' selected':'').'>'.catalog_h((string)$g['name']).'</option>';echo'</select></label><label>Dependency type<select name="dependency_type"><option value="all"'.(!$baseGameOnly?' selected':'').'>All missing dependencies</option><option value="base_game"'.($baseGameOnly?' selected':'').'>Official base-game dependencies only</option></select></label><button type="submit">Apply filters</button></form></div></section><div class="missing-summary">';catalog_stat_card('Missing objects',$missingObjects,'Requested object identities that did not resolve',$missingObjects?'attention':'good');catalog_stat_card('Required packages',$missingPackages,'Logical packages referenced by those imports',$missingPackages?'attention':'good');catalog_stat_card('Affected files',$filesWithMissing,'Files containing unresolved imports',$filesWithMissing?'attention':'good');echo'</div>';
if($packageRows!==[]){echo'<section class="ui-section"><div class="ui-section__header"><div><h2>At a glance</h2><p>Unresolved objects grouped by required package. This does not mean the package itself is absent.</p></div></div><div class="ui-section__body"><div class="missing-package-summary">';foreach($packageRows as $p){$name=(string)$p['required_package'];echo'<a class="missing-package-pill" href="'.catalog_h(game_missing_url($gameId,$type,['package'=>$name])).'"><span class="mono">'.catalog_h($name).'</span><strong>'.(int)$p['missing_object_rows'].'</strong><span class="muted small">objects / '.(int)$p['requiring_file_count'].' files</span></a>';}echo'</div></div></section>';}
$title=$selectedPackage!==''?'Unresolved objects requiring '.$selectedPackage:'Unresolved object identities';echo'<section class="ui-section"><div class="ui-section__header"><div><h2>'.catalog_h($title).'</h2><p>Each provider shows what the importing file expected, what was actually found, and the exact reason VerifyImport rejected it.</p></div>';if($selectedPackage!=='')echo'<a class="button secondary" href="'.catalog_h(game_missing_url($gameId,$type)).'">Show all</a>';echo'</div><div class="ui-section__body">';if($rows===[])echo CatalogUi::emptyState('No unresolved dependency objects','Nothing currently matches the selected scope.');else foreach($rows as $r){$pkg=(string)$r['required_package'];$class=game_missing_import_class((string)$r['class_package'],(string)$r['class_name']);$providers=(array)($r['provider_candidates']??[]);echo'<article class="missing-detail"><div class="missing-detail__title"><strong><a href="file-info.php?id='.(int)$r['file_id'].'">'.catalog_h((string)$r['owner_package_name']).'</a></strong><a class="muted" href="file-examine.php?id='.(int)$r['file_id'].'">'.catalog_h((string)$r['owner_original_name']).'</a></div><div class="missing-detail__grid"><div class="missing-detail__cell"><span class="missing-label">1. LOOKING FOR</span><div class="gm-wanted"><strong class="mono">'.catalog_h((string)$r['required_object_path']).'</strong><span>Object: <b class="mono">'.catalog_h((string)$r['import_object_name']).'</b></span><span>Class: <b class="mono">'.catalog_h($class!==''?$class:'(not recorded)').'</b></span><span>Outer: <b class="mono">'.catalog_h($pkg).'</b></span></div></div><div class="missing-detail__cell"><span class="missing-label">2. AVAILABLE PACKAGE FILES</span>';
if($providers===[])echo'<div class="mismatch-reason">No verified physical file providing '.catalog_h($pkg).' exists.</div>';else foreach($providers as $provider)echo'<div class="provider-block"><a href="file-info.php?id='.(int)$provider['file_id'].'"><strong>'.catalog_h((string)$provider['original_name']).'</strong></a><div class="muted small">File #'.(int)$provider['file_id'].' · '.catalog_h((string)$provider['source_kind']).' provider</div></div>';echo'</div><div class="missing-detail__cell"><span class="missing-label">3. FOUND / VERIFYIMPORT RESULT</span>';
if($providers===[])echo'<div class="gm-result gm-result--bad">✗ PACKAGE NOT PRESENT — no candidate export can be checked.</div>';else foreach($providers as $provider){$candidates=(array)($provider['candidate_rows']??[]);echo'<div class="provider-block"><strong>FOUND IN '.catalog_h((string)$provider['original_name']).' #'.(int)$provider['file_id'].'</strong>';if($candidates===[]){echo'<div class="gm-result gm-result--bad">✗ OBJECT NOT PRESENT<div class="gm-diff"><span>Expected object: <b class="mono">'.catalog_h((string)$r['import_object_name']).'</b></span><span>Got: <b>no export with this object name</b></span></div></div>';continue;}foreach($candidates as $candidate){$s=catalog_dependency_candidate_summary($r,$candidate,(string)($candidate['outer_path']??''));$public=(bool)$s['public'];$all=(bool)$s['object_match']&&(bool)$s['class_package_match']&&(bool)$s['class_name_match']&&(bool)$s['outer_match']&&$public;$failed=[];if(!$s['object_match'])$failed[]='OBJECT';if(!$s['class_package_match']||!$s['class_name_match'])$failed[]='CLASS';if(!$s['outer_match'])$failed[]='OUTER';if(!$public)$failed[]='PRIVATE EXPORT';echo'<div class="candidate"><div><strong>Export #'.(int)$candidate['export_index'].'</strong></div><table class="compare"><thead><tr><th>Field</th><th>Expected</th><th>Got</th><th>Result / difference</th></tr></thead><tbody>';
echo gm_compare_row('ObjectName',(string)$s['wanted_object'],(string)$s['actual_object'],(bool)$s['object_match']);echo gm_compare_row('ClassPackage',(string)$s['wanted_class_package'],(string)$s['actual_class_package'],(bool)$s['class_package_match']);echo gm_compare_row('ClassName',(string)$s['wanted_class_name'],(string)$s['actual_class_name'],(bool)$s['class_name_match']);echo gm_compare_row('Outer / parent path',(string)$s['wanted_outer_path'],(string)$s['actual_outer_path'],(bool)$s['outer_match']);echo gm_compare_row('RF_Public','yes',(string)($public?'yes':'no').' · '.(string)$s['flags_hex'],$public);echo'</tbody></table><div class="muted small">Serialized candidate outer index: '.(int)$s['actual_outer_index'].'</div><div class="gm-result '.($all?'gm-result--good':'gm-result--bad').'">'.($all?'✓ ALL VALUES MATCH — investigate resolver/projection state.':'✗ REJECTED: '.catalog_h(implode(' + ',$failed)).' MISMATCH').'</div></div>';}}echo'</div></div></article>';}echo'</div></section>';catalog_foot();}catch(Throwable $error){if(!headers_sent())catalog_head('Game missing dependencies error');echo CatalogUi::alert('danger',$error->getMessage(),'The filtered missing-dependency page could not be loaded.');catalog_foot();}
